const requestedLanguage=new URLSearchParams(location.search).get('lang');
if(['ar','fr'].includes(requestedLanguage))localStorage.setItem('alkarna-site-language',requestedLanguage);
globalThis.karnaLocale={text:translateText,tag:localeTag,number:formatNumber};
const database=new ShopDatabase();
let verifiedSetupIdentity=null;
async function readSetupIdentity(){
 if(!window.NativeFiles?.licenseStatus)return null;
 const status=await window.NativeFiles.licenseStatus();
 if(!status.valid||!status.license?.customerName?.trim()||!status.license?.storeName?.trim())throw new Error('تعذّر قراءة هوية ملف التفعيل');
 return {name:status.license.customerName.trim(),shop:status.license.storeName.trim()};
}
let preparedExport=null;
async function offerExport(name,blob){const response=await fetch('/api/export',{method:'POST',body:blob});if(!response.ok)throw new Error('تعذر تجهيز رابط التنزيل');preparedExport={name,url:(await response.json()).url};modal='site-export-ready';render()}
let actor=null,appUsers=[],ready=false,busy=false,authMode='login',userEdit=null,restoreFile=null,restorePlan=null;
let baseAct=act,baseRender=render,baseEffect=invoiceEffect,baseSheet=sheet,baseUtility=utility,baseSettings=settings,baseInvoice=invoice,baseProduct=productDetail,baseAccount=accountDetail,baseHome=home,baseNewRecord=newRecord;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const time=()=>new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});
const roleNames={owner:'مالك',manager:'مدير',accountant:'محاسب',sales:'بيع فقط',custom:'مخصص'};
const publicUser=u=>({id:u.id,name:u.name,username:u.username,role:u.role,active:u.active,capabilities:u.capabilities});
const can=cap=>!!actor&&(actor.role==='owner'||(actor.capabilities||PRESETS[actor.role]||[]).includes(cap));
const sessionKey='alkarna-local-session';
const digest=async text=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))].map(x=>x.toString(16).padStart(2,'0')).join('');
const fail=t=>{const target=document.querySelector('#form-error,.auth-error');if(target)target.innerHTML=`<p class="error" role="alert">${esc(t)}</p>`;else toast(t)};
const showModal=(name)=>{modal=name;render()};
const modalMarkup=(title,body,submit='',label='حفظ',kind='')=>`<div class="overlay"><section class="sheet ${kind}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-handle"></div><div class="sheet-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="إغلاق">${icon('close')}</button></div><div class="sheet-body"><form id="sheet-form">${body}</form><div id="form-error"></div></div>${submit?primary(label,submit):''}</section></div>`;
