icons.phone='M7 3H3v4c0 8 6 14 14 14h4v-4l-5-2-2 2a13 13 0 0 1-7-7l2-2-2-5Z';
icons.message='M21 11a9 9 0 0 1-9 9 10 10 0 0 1-4-1l-5 2 1-5a9 9 0 1 1 17-5Z M8 10h8 M8 14h5';
icons.logout='M10 3H4v18h6 M9 12h12 M17 8l4 4-4 4';
function accountMenuMarkup(){
 const name=actor?.name||'',role=roleNames[actor?.role]||'',initial=Array.from(name.trim())[0]||'ك';
 return `<div class="account-identity"><span class="account-avatar" aria-hidden="true">${esc(initial)}</span><div class="account-identity-copy"><h3>${esc(name)}</h3><span class="account-role">${role}</span><p>${esc(S.branding||'الكرنه')}</p></div></div><div class="account-appearance"><h3>مظهر التطبيق</h3><div class="account-theme-picker" role="group" aria-label="مظهر التطبيق">${['dark','light'].map(mode=>`<button type="button" data-action="appearance:${mode}" aria-pressed="${previewAppearance29===mode}">${appearanceIcon29(mode)}<span>${mode==='dark'?'ليلي':'نهاري'}</span>${previewAppearance29===mode?icon('check'):'<span class="theme-check-space"></span>'}</button>`).join('')}</div></div><div class="account-links"><button type="button" data-action="site:support">${icon('support')}<span><strong>تواصل مع الدعم</strong><small dir="ltr">49823328</small></span>${icon('arrow')}</button>${window.NativeHost?`<button type="button" data-action="site:activation">${icon('shield')}<span><strong>ترخيص الجهاز</strong><small>كود الجهاز وحالة التفعيل</small></span>${icon('arrow')}</button>`:''}</div><button type="button" class="account-logout" data-action="site:logout">${icon('logout')}<span>تسجيل الخروج</span></button>`;
}
function supportMarkup(){return `<div class="support-intro"><img class="support-image" src="assets/support-contact.png" alt="الكرنه" width="1254" height="1254"><div><h3>معك لتشغيل محلك</h3><p>للمساعدة أو تجديد الترخيص، تواصل معنا على الرقم</p><b dir="ltr">49823328</b></div></div><div class="support-methods"><a class="support-whatsapp" href="https://wa.me/22249823328" target="${window.NativeHost?'_self':'_blank'}" rel="noopener noreferrer">${icon('message')}<span>واتساب</span>${icon('arrow')}</a><a href="tel:49823328">${icon('phone')}<span>اتصال هاتفي</span>${icon('arrow')}</a></div><p class="support-hint">مساعدة في استخدام التطبيق أو تجديد الترخيص؟ تواصل معنا وسنساعدك.</p>`}
function stateForSave(){if(S.featureSchema!==2)prepareFeatureState(S);const state=structuredClone(S);state.users=appUsers.map(publicUser);delete state.saleParty;return state}
function refreshUserState(){S.users=appUsers.map(publicUser)}
async function loadUsers(){appUsers=await database.all('users');refreshUserState()}
async function makeSession(user){const token=crypto.randomUUID()+crypto.randomUUID();await database.put('meta',{id:'session:'+await digest(token),user:user.id,expiresAt:Date.now()+12*60*60*1000});sessionStorage.setItem(sessionKey,token);actor=publicUser(user)}
async function readSession(){const token=sessionStorage.getItem(sessionKey);if(!token)return;const row=await database.get('meta','session:'+await digest(token));const user=appUsers.find(u=>u.id===row?.user&&u.active!==false);if(row?.expiresAt>Date.now()&&user)actor=publicUser(user)}
async function logout(){savePosDraft();const token=sessionStorage.getItem(sessionKey);if(token)await database.put('meta',{id:'session:'+await digest(token),expiresAt:0});sessionStorage.removeItem(sessionKey);actor=null;modal=null;cart=[];editingId=null;history=[];authMode='login';render()}
function authScreen(){const setup=authMode==='setup',licensed=setup&&verifiedSetupIdentity;return `<main class="auth-screen"><section class="auth-card"><div class="auth-brand"><img class="brand-logo" src="assets/alkarna-logo.png" alt="" width="44" height="44"><span>الكرنه</span></div>${languagePicker()}<h1>${setup?'إنشاء بيانات الدخول':'تسجيل الدخول'}</h1><p>${licensed?'اختر اسم مستخدم وكلمة مرور لحسابك المحلي.':setup?'أنشئ حساب المالك. بيانات المحل تُحفظ على هذا الجهاز وتبقى بعد إغلاق الموقع.':'ادخل بحسابك المحلي لمتابعة البيع والمخزون والحسابات.'}</p>${licensed?`<section class="licensed-identity" aria-label="معلومات من ملف التفعيل"><h2>معلومات من ملف التفعيل</h2><dl><div><dt>اسم صاحب الترخيص</dt><dd data-user-content>${esc(licensed.name)}</dd></div><div><dt>اسم المحل</dt><dd data-user-content>${esc(licensed.shop)}</dd></div></dl><small>هذه المعلومات مأخوذة من ملف التفعيل الموثّق.</small></section>`:''}<form id="site-auth-form">${setup&&!licensed?field('اسم المالك',input('name','text'))+field('اسم المحل',input('shop','text')):''}${field('اسم المستخدم',input('username','text'))}${field('كلمة المرور',input('password','password'))}</form><div class="auth-error"></div>${primary(setup?'إنشاء المحل':'دخول',setup?'site:setup':'site:login')}<p class="appearance-note" style="margin-top:12px">${setup?'اختر كلمة مرور لا تقل عن 4 أحرف.':'حسابات هذا الموقع تخص البيانات الموجودة على هذا الجهاز.'}</p></section></main>`}

let partyMetricSelection=null;
const partyMetricLabels={receivable:'لنا',payable:'علينا',trade:'المبيعات',profit:'الربح الإجمالي',cashIn:'المستلم',cashOut:'المدفوع',invoiceCount:'عدد الفواتير'};
function partyMetricLabel(summary,key){return key==='trade'&&summary.type==='supplier'?'المشتريات':partyMetricLabels[key]}
function partySummaryMarkup(summary,debts=false,detail=false){
 const keys=debts?['receivable','payable']:summary.type==='customer'?['trade','profit','cashIn','cashOut']:['trade','invoiceCount','cashOut','cashIn'];
 const title=debts?'الأرصدة الحالية':detail?'إجماليات الحساب':summary.type==='customer'?'إجماليات العملاء':'إجماليات الموردين';
 return `<section class="party-summary ${debts?'party-debts':'party-history-summary'}" aria-label="${title}"><div class="party-summary-heading"><h2>${title}</h2><small>${debts?'حتى الآن':'كل الفترة'}</small></div><div class="party-summary-grid">${keys.map(key=>{const n=summary.values[key],tone=key==='payable'||key==='cashOut'||key==='profit'&&n<0?'negative':key==='receivable'||key==='cashIn'||key==='profit'&&n>0?'positive':'';return `<button type="button" class="party-stat" data-metric="${key}" data-value="${n}" data-action="site:party-metric:${summary.type}:${summary.partyId??'all'}:${key}" aria-label="${esc((localStorage.getItem('alkarna-site-language')==='fr'?(translations[partyMetricLabel(summary,key)]||partyMetricLabel(summary,key))+' — Afficher l’origine':partyMetricLabel(summary,key)+' — عرض المصدر'))}"><span class="party-stat-label">${partyMetricLabel(summary,key)}</span>${key==='invoiceCount'?`<b class="party-stat-count">${n.toLocaleString('en-US')}</b>`:money(n,'sm',tone)}</button>`}).join('')}</div></section>`;
}
parties=function(){
 const availableTypes=['customer','supplier'].filter(type=>can((type==='customer'?'customers':'suppliers')+'.view'));
 if(!availableTypes.length)return empty('غير متاح','لا تسمح صلاحيات حسابك بعرض هذه الحسابات.');
 if(!availableTypes.includes(partyType))partyType=availableTypes[0];
 const summary=partyFinancialSummary(S,partyType),list=summary.parties.filter(p=>searchMatches(p.name+' '+p.phone,search));
 const directory=list.length?boundedTableHtml(`<div class="register-table-shell party-directory"><div class="register-scroll" role="region" aria-label="${partyType==='customer'?'العملاء':'الموردون'}"><table class="register-table"><colgroup><col style="width:12%"><col style="width:36%"><col style="width:24%"><col style="width:28%"></colgroup><thead><tr><th scope="col">الرقم</th><th scope="col">${partyType==='customer'?'العميل':'المورد'}</th><th scope="col">الهاتف</th><th scope="col">الرصيد</th></tr></thead><tbody>${list.map((p,i)=>`<tr data-action="ledger:${p.id}"><td>${i+1}</td><td><button class="party-directory-name" data-action="ledger:${p.id}">${esc(p.name)}</button></td><td class="party-directory-phone"><span dir="ltr">${esc(p.phone||'—')}</span></td><td>${money(Math.abs(p.balance),'xs',p.balance?(partyNetBalance(p)<0?'negative':'positive'):'')}</td></tr>`).join('')}</tbody></table></div></div>`):empty(search?'لا توجد نتائج':'لا توجد حسابات',search?'جرّب اسمًا أو رقم هاتف آخر.':'أضف عميلًا أو موردًا لتسجيل حركاته.',search?'':'open:party',partyType==='customer'?'إضافة عميل':'إضافة مورد');
 return `<div class="tabs">${[['customer','العملاء'],['supplier','الموردون']].filter(([id])=>availableTypes.includes(id)).map(([id,title])=>`<button class="${partyType===id?'active':''}" data-action="partytype:${id}">${title}</button>`).join('')}</div>${partySummaryMarkup(summary,true)}${searchField('ابحث بالاسم أو الهاتف')}<div id="results">${directory}</div>${partySummaryMarkup(summary)}`;
};
const accountLedgerBeforeSummary=ledger;
function partyAccountHistory(party){
 const records=liveRecords().filter(r=>r.party===party.id);if(!records.length)return section('حركات الحساب')+empty('لا توجد حركات في الفترة','ستظهر الفواتير والحركات هنا بعد تسجيلها.');
 return `<div class="party-account-history">${reportSourceTable31('حركات الحساب',['التاريخ','النوع','المبلغ'],records,r=>({action:'invoice:'+r.id,cells:[`<span class="party-movement-date" dir="ltr">${esc(r.date||'')} <small>${esc(r.time||'')}</small></span>`,esc(documentLabels[r.kind]||r.kind),money(r.total,'xs',['purchase','pay','expense','withdraw'].includes(r.kind)?'negative':['sale','receive'].includes(r.kind)?'positive':'')]}))}</div>`;
}
ledger=function(){
 const p=S.parties.find(p=>p.id===selected);if(!p)return accountLedgerBeforeSummary();
 const summary=partyFinancialSummary(S,p.type,p.id);
 return `<div class="party-account-heading"><div><small class="party-account-type">${p.type==='customer'?'حساب العميل':'حساب المورد'}</small><h2>${esc(p.name)}</h2><small dir="ltr">${esc(p.phone||'—')}</small></div><button type="button" class="icon-btn" data-action="open:partyedit" aria-label="تعديل الحساب">${icon('edit')}</button></div><div class="party-account-metrics">${partySummaryMarkup(summary,true,true)}${partySummaryMarkup(summary,false,true)}</div>${partyAccountHistory(p)}`;
};
function partyMetricSourceMarkup(){
 const selection=partyMetricSelection,summary=partyFinancialSummary(S,selection.type,selection.id),key=selection.key,label=partyMetricLabel(summary,key),value=summary.values[key],count=key==='invoiceCount',people=new Map(summary.parties.map(p=>[p.id,p]));
 let formula=key==='trade'?(summary.type==='customer'?'مجموع فواتير البيع الفعالة بعد المرتجعات المسجلة، سواء كانت نقدية أو على الحساب.':'مجموع فواتير الشراء الفعالة، سواء كانت نقدية أو على الحساب.'):key==='profit'?'ربح البيع المحفوظ وقت الفاتورة، دون طرح المصاريف. تغيير سعر شراء المنتج اليوم لا يغيّر هذا الرقم.':key==='invoiceCount'?'كل فاتورة شراء فعالة تُحسب مرة واحدة، بغض النظر عن عدد بنودها.':key==='cashIn'?'المدفوع مع فواتير البيع وحركات الاستلام الفعلية من هذه الحسابات. الفواتير الآجلة لا تُحسب استلامًا.':key==='cashOut'?'المدفوع مع فواتير الشراء وحركات الدفع الفعلية لهذه الحسابات. الفواتير الآجلة لا تُحسب دفعًا.':'المستحق الحالي لكل حساب على حدة، دون مقابلة رصيد عميل أو مورد برصيد حساب آخر.';
 const items=partyMetricContributions(S,summary,key);let body='';
 if(['receivable','payable'].includes(key)&&summary.partyId!==null){
  const p=summary.parties[0],net=partyNetBalance(p),orientation=p.type==='supplier'?-1:1,opening=reportNumber31(S.opening?.parties?.[p.id])*orientation;
  const records=S.records.filter(r=>effectivePartyRecord(r)&&partyDelta(r,p.id)!==0),delta=r=>partyDelta(r,p.id)*orientation,residual=reportRound31(net-opening-reportAdd31(records,delta));
  formula='صافي الحساب = رصيد البداية + أثر الفواتير والاستلام والدفع. الصافي الموجب لنا والسالب علينا؛ يظهر المستحق في جهته فقط.';
  body=`<div class="report-trace-total"><span>صافي رصيد البداية</span>${money(opening,'xs',opening<0?'negative':'')}</div>`+reportOperationTable31('حركات '+p.name,records,delta)+`<div class="report-trace-total"><span>صافي الحساب</span>${money(net,'xs',net<0?'negative':net>0?'positive':'')}</div>`+(Math.abs(residual)>.005?`<p class="report-trace-alert">فرق عن الحركات ${money(residual,'xs')}</p>`:'');
 }else if(['receivable','payable'].includes(key))body=reportSourceTable31(label,['الحساب','المستحق'],items,row=>({action:`site:party-metric:${summary.type}:${row.party.id}:${key}`,cells:[esc(row.party.name),money(row.value,'xs',key==='receivable'?'positive':'negative')]}));
 else body=reportSourceTable31(label,['العملية',count?'العدد':'القيمة'],items,row=>({action:'invoice:'+row.record.id,cells:[`<strong>${esc(documentLabels[row.record.kind]||row.record.kind)}</strong><small>${esc(people.get(row.record.party)?.name||'')} · ${esc(row.record.date||'')}<br>${esc(row.record.number||row.record.kind.toUpperCase()+'-'+row.record.id)}</small>`,count?'1':money(row.value,'xs',row.value<0?'negative':'')]}));
 return `<div class="party-metric-source"><div class="report-trace-heading"><h3>${esc(summary.partyId!==null?summary.parties[0]?.name||'':summary.type==='customer'?'العملاء':'الموردون')}</h3><small>${['receivable','payable'].includes(key)?'حتى الآن':'كل الفترة'}</small></div><p class="report-context-note">${formula}</p><div class="report-trace-total"><strong>${label}</strong>${count?`<b>${value.toLocaleString('en-US')}</b>`:money(value,'sm',key==='payable'?'negative':key==='receivable'?'positive':'')}</div>${body}</div>`;
}

invoiceEffect=function(record,sign){baseEffect(record,sign);for(const account of S.accounts)account.balance=Math.round((account.balance+Number.EPSILON)*100)/100;for(const party of S.parties)party.balance=Math.round((party.balance+Number.EPSILON)*100)/100};
newRecord=function(kind){const result=baseNewRecord(kind);if(!editingId){result.date=today();result.time=time()}return result};
inPeriod=function(r){if(period==='all')return true;const date=r.date||today();return period==='today'?date===today():date>=dateFrom&&date<=dateTo};
home=function(){return baseHome().replace('الأحد، 4 أكتوبر',new Date().toLocaleDateString(localeTag(),{weekday:'long',day:'numeric',month:'long'}))};
settings=function(){return baseSettings().replace('العربية · معاينة RTL',(localStorage.getItem('alkarna-site-language')||'ar')==='fr'?'Français · LTR':'العربية · RTL')+`<div class="data-toolbar"><button data-action="site:audit">سجل النشاط</button><button data-action="site:archived">المؤرشفات</button></div>`+`<div class="app-session"><div><strong>${esc(actor?.name||'')}</strong><small> · ${roleNames[actor?.role]||''}</small></div><button data-action="site:logout">تسجيل الخروج</button></div>`};
const sellerSettings=settings;
settings=function(){return sellerSettings()+section('الدعم والمساعدة')+listMenu([['تواصل مع الدعم','واتساب أو اتصال · 49823328','support','site:support'],...(window.NativeHost?[['ترخيص الجهاز','كود الجهاز وحالة التفعيل','shield','site:activation']]:[])])};
function userList(){return section('المستخدمون')+`<div class="action-catalog compact-catalog">${appUsers.map(u=>`<button class="catalog-item" data-action="site:user:${u.id}"><span class="catalog-icon">${icon('shield')}</span><span class="catalog-copy"><strong>${esc(u.name)}</strong><small>${esc(u.username)} · ${roleNames[u.role]} · ${u.active===false?'موقوف':'فعال'}</small></span>${icon('arrow')}</button>`).join('')}</div><div class="management-actions">${primary('إضافة مستخدم','site:new-user')}</div>`}
function backupScreen(){return `${section('حفظ البيانات')}${listMenu([['تنزيل نسخة احتياطية','المستندات والأرصدة والمخزون والمستخدمون','shield','site:backup'],['استعادة نسخة الموقع','معاينة النسخة قبل الاستبدال','shield','site:restore'],['تنزيل نسخة ما قبل الاستعادة','نسخة الأمان المحفوظة قبل آخر استبدال','shield','site:previous-backup'],['استيراد نسخة كونتا أوفلاين','ملف النسخة الرسمي بصيغة JSON','box','site:desktop-import']])}<div class="notice">النسخة تحتوي بيانات المحل والحسابات المحلية. احتفظ بها خارج المتصفح؛ مسح بيانات الموقع يحذف البيانات المحلية.</div>`}
utility=function(){if(view==='users')return userList();if(view==='backup')return backupScreen();if(view==='login')return `<div class="app-session"><strong>${esc(actor?.name||'')}</strong><button data-action="site:logout">تسجيل الخروج</button></div>`;if(view==='branding')return `<form id="branding-form">${field('اسم المحل',input('name','text',S.branding||''))}${field('الهاتف',input('phone','tel',S.brandInfo?.phone||''))}${field('العنوان',input('address','text',S.brandInfo?.address||''))}${field('تذييل الفاتورة',input('footer','text',S.brandInfo?.footer||'شكرًا لزيارتكم'))}</form>`;return baseUtility().replace(/هذه معاينة[^<]*/g,'')};
productDetail=function(){const html=baseProduct(),p=S.products.find(p=>p.id===selected);return html+(p&&can('products.delete')?`<div class="management-actions"><button class="negative" data-action="site:archive-product:${p.id}">أرشفة المنتج</button></div>`:'')};
accountDetail=function(){const html=baseAccount();return html+(can('banks.edit')?`<div class="management-actions"><button data-action="site:edit-account:${selected}">تعديل وسيلة الدفع</button><button data-action="site:account-adjust:${selected}">تصحيح الرصيد</button>${can('banks.delete')?`<button class="negative" data-action="site:archive-account:${selected}">أرشفة وسيلة الدفع</button>`:''}</div>`:'')};
invoice=function(){const r=S.records.find(r=>r.id===selected);return r?invoiceDocument(S,r,{esc,money,icon,labels:documentLabels,atSource:invoiceIsAtSource(r)}):empty('العملية غير موجودة','عد إلى السجل.')};

sheet=function(){if(modal==='site-party-metric'&&partyMetricSelection)return modalMarkup(partyMetricLabel(partyFinancialSummary(S,partyMetricSelection.type,partyMetricSelection.id),partyMetricSelection.key),partyMetricSourceMarkup());if(modal==='site-export-ready'&&preparedExport)return modalMarkup('الملف جاهز',`<p class="notice">${esc(preparedExport.name)}</p><a class="export-download-link" href="${preparedExport.url}" download="${esc(preparedExport.name)}">تنزيل الملف</a>`);if(modal==='site-export')return modalMarkup('تصدير السجل','<p class="notice">يشمل التصدير جميع بيانات المستندات وبنودها ضمن الفترة والنوع والبحث المختار، بما فيها التفاصيل المخفية في القائمة.</p><div class="export-output-options"><button type="button" data-action="site:export-excel"><span class="output-file-badge excel">XLSX</span><span><strong>ملف إكسل</strong><small>جداول قابلة للفرز والتحليل</small></span></button><button type="button" data-action="site:export-pdf"><span class="output-file-badge pdf">PDF</span><span><strong>ملف PDF</strong><small>تنزيل التقرير مباشرة</small></span></button><button type="button" data-action="site:export-print"><span class="output-file-badge">'+icon('print')+'</span><span><strong>الطباعة</strong><small>اختيار الطابعة وإعداداتها</small></span></button></div>');if(modal==='site-account-menu')return modalMarkup('حساب المستخدم',accountMenuMarkup(),'','حفظ','account-sheet');if(modal==='site-support')return modalMarkup('تواصل مع الدعم',supportMarkup(),'','حفظ','support-sheet');if(modal==='site-audit')return modalMarkup('سجل النشاط',`<div class="panel">${(S.auditEvents||[]).slice().reverse().map(e=>`<div class="row"><span class="copy"><strong>${esc(e.userName)}</strong><small>${esc(e.at.slice(0,16).replace('T',' '))} · ${esc(activityName(e.action))}</small></span></div>`).join('')||'<p>لا يوجد نشاط بعد</p>'}</div>`);if(modal==='site-archived')return modalMarkup('المؤرشفات',`<div class="panel">${[...S.products.filter(p=>p.archived).map(p=>({...p,entity:'product'})),...S.accounts.filter(p=>p.archived).map(p=>({...p,entity:'account'}))].map(p=>`<button class="row" data-action="site:unarchive:${p.entity}:${p.id}"><strong>${esc(p.name)}</strong><span>إعادة التفعيل</span></button>`).join('')||'<p>لا توجد مؤرشفات</p>'}</div>`);if(modal==='site-language')return modalMarkup('إعدادات اللغة',`<div class="appearance-picker"><button type="button" data-action="site:language:ar">العربية</button><button type="button" data-action="site:language:fr">Français</button></div>`);if(modal==='site-user'){const u=appUsers.find(u=>u.id===userEdit);return modalMarkup(u?'تعديل المستخدم':'إضافة مستخدم',field('الاسم',input('name','text',u?.name||''))+field('اسم المستخدم',input('username','text',u?.username||''))+field(u?'كلمة مرور جديدة — اتركها فارغة للإبقاء':'كلمة المرور',input('password','password'))+field('الصلاحيات',`<select name="role">${Object.entries(roleNames).filter(([r])=>r!=='owner'||u?.role==='owner').map(([r,n])=>`<option value="${r}" ${u?.role===r?'selected':''}>${n}</option>`).join('')}</select>`)+(u&&u.id!==actor.id?field('الحالة',`<select name="active"><option value="true" ${u.active!==false?'selected':''}>فعال</option><option value="false" ${u.active===false?'selected':''}>موقوف</option></select>`):''),'site:save-user')}
  if(modal==='site-import')return modalMarkup('اختيار نسخة احتياطية','<label class="backup-file-picker"><span class="backup-file-heading">اختر ملف النسخة</span><small data-backup-file-name>JSON · لم يُحدد ملف</small><input id="backup-file" type="file" accept=".json,application/json" aria-label="اختر ملف النسخة"></label><details class="paste-backup"><summary>أو لصق نص النسخة</summary><label class="field"><span>نص النسخة JSON</span><textarea id="backup-json" aria-label="نص النسخة JSON" rows="6" dir="ltr" spellcheck="false"></textarea></label></details><p class="notice">لن تُستبدل البيانات قبل عرض ملخص النسخة وتأكيد الاستعادة.</p>','site:review-import','مراجعة النسخة');
  if(modal==='site-import-review')return modalMarkup('تأكيد الاستعادة',`<div class="upload-summary">${esc(restorePlan?.state?.branding||'المحل')}<br>${restorePlan.state.products.length} منتجات · ${restorePlan.state.parties.length} أطراف<br>${restorePlan.state.records.length} مستندات · ${restorePlan.state.accounts.length} حسابات</div><p class="notice">ستحل هذه النسخة محل بيانات المحل الحالية. ستُحفظ نسخة أمان من البيانات السابقة قبل الاستبدال.</p>`,'site:confirm-import','استعادة النسخة');
  if(modal==='site-account-edit'){const a=S.accounts.find(a=>a.id===selected);return modalMarkup('تعديل وسيلة الدفع',field('الاسم',input('name','text',a?.name||'')),'site:save-account')}
  if(modal==='site-account-adjust'){const a=S.accounts.find(a=>a.id===selected);return modalMarkup('تصحيح رصيد الحساب',field('الرصيد الجديد',input('balance','number',a?.balance||0))+field('سبب التصحيح',input('note'))+'<p class="notice">يُسجّل فرق الرصيد كمستند إيداع أو سحب قابل للتعديل والإلغاء.</p>','site:post-account-adjust')}
  const html=baseSheet();return html.replace(/تم حفظ ([^<]*?) في المعاينة/g,'تم حفظ $1').replace('جرّب 001 أو 002.','').replace('معاينة الفاتورة','عرض الفاتورة')}

function permissionFor(action){if(action.startsWith('partytype:'))return (action.split(':')[1]==='supplier'?'suppliers':'customers')+'.view';if(action.startsWith('site:party-metric:'))return (action.split(':')[2]==='supplier'?'suppliers':'customers')+'.view';if(action==='site:seed-demo')return 'settings.backup.manage';const [a,b]=action.split(':');if(a==='source-location'){const r=S.records.find(r=>r.id===Number(b)),target=r&&documentSourceDestination(r),party=S.parties.find(p=>p.id===target?.id);return target?.view==='sale-source'?'pos.view':target?.view==='purchase-source'?'purchases.view':target?.view==='expenses'?'expenses.view':target?.view==='ledger'?(party?.type==='supplier'?'suppliers.view':'customers.view'):['accounts','account'].includes(target?.view)?'banks.view':['transfer','adjustment'].includes(target?.view)?'warehouses.view':'records.view';}if(a==='cash'||a==='open'&&['receive','pay','partyCash'].includes(b))return can('customers.collect')?'customers.collect':'suppliers.pay';if(a==='post-party'){const f=form(),p=S.parties.find(p=>p.id===Number('party' in f?f.party:selected));return (p?.type==='supplier'?'suppliers.pay':'customers.collect')+(editingId?'.edit':'')}if(['source','void','confirm-void'].includes(a)){const r=S.records.find(r=>r.id===Number(b||selected));if(r&&['receive','pay'].includes(r.kind)){const p=S.parties.find(p=>p.id===r.party);return (p?.type==='supplier'?'suppliers.pay':'customers.collect')+(a==='source'?'.edit':'.delete')}}if(a==='pos')return ['new-party','save-party'].includes(b)?(saleType==='sale'?'customers':'suppliers')+'.create':(saleType==='sale'?'pos':'purchases')+'.'+(editingId?'edit':'create');if(['site:export','site:export-excel','site:export-pdf','site:export-print'].includes(action))return view==='reports'?'reports.view':'records.view';if(action==='site:print')return ['sale','purchase'].includes(S.records.find(r=>r.id===selected)?.kind)?'pos.view':'records.view';const kindCap=(kind,suffix='create')=>({sale:'pos',purchase:'purchases',expense:'expenses',receive:'customers.collect',pay:'suppliers.pay',deposit:'banks.deposit_withdraw',withdraw:'banks.deposit_withdraw',transfer:'banks.transfer',stocktransfer:'warehouses.transfer',adjustment:'warehouses.adjust',offset:'customers.collect'}[kind]||'records')+(['receive','pay','deposit','withdraw','transfer','stocktransfer','adjustment','offset'].includes(kind)?'':'.'+suffix);if(a==='low')return 'products.view';if(a==='product')return 'products.view';if(a==='account')return 'banks.view';if(a==='ledger')return (S.parties.find(p=>p.id===Number(b))?.type==='supplier'?'suppliers':'customers')+'.view';if(a==='add'||a==='qty'||a==='price')return kindCap(saleType,editingId?'edit':'create');if(a==='partytab')return (b==='supplier'?'suppliers':'customers')+'.view';if(a==='explain')return b==='document'?'records.view':'reports.view';if(a==='invoice')return 'records.view';if(a==='go')return {'sale-source':'pos.view','purchase-source':'purchases.view',cash:'records.view',home:null,operations:'records.view',inventory:'products.view',parties:partyType==='supplier'?'suppliers.view':'customers.view',accounts:'banks.view',reports:'reports.view',users:'settings.users.manage',settings:'settings.view',backup:'settings.backup.manage',branding:'settings.branding.manage',warehouses:'warehouses.view',audit:'warehouses.inventory.view',transfer:'warehouses.transfer',adjustment:'warehouses.adjust',purchase:'purchases.view',sale:'pos.view',expenses:'expenses.view',returns:'records.view',offset:'customers.collect'}[b];if(a==='new')return kindCap(b);if(a==='source'){const r=S.records.find(r=>r.id===Number(b));return kindCap(r?.kind,'edit')}if(a==='void'||a==='confirm-void'){const r=S.records.find(r=>r.id===Number(b||selected));return kindCap(r?.kind,'delete')}if(a==='post-sale')return kindCap(saleType,editingId?'edit':'create');if(a==='post-cash')return kindCap({expense:'expense',deposit:'deposit',withdraw:'withdraw',cashtransfer:'transfer'}[modal],editingId?'edit':'create');if(a==='post-party'){const p=S.parties.find(p=>p.id===Number(form().party||selected));return kindCap(p?.type==='supplier'?'pay':'receive',editingId?'edit':'create')}if(a==='commit-pending')return kindCap(pendingRecord?.kind,editingId?'edit':'create');if(a==='save-product')return 'products.'+(modal==='productedit'?'edit':'create');if(a==='save-party')return (partyType==='supplier'?'suppliers':'customers')+'.'+(modal==='partyedit'?'edit':'create');if(a==='save-account')return 'banks.create';if(a==='warehouse-create')return 'warehouses.create';if(a==='warehouse-edit'||a==='save-warehouse')return 'warehouses.'+(warehouseEdit?'edit':'create');if(a==='open')return {product:'products.create',productedit:'products.edit',party:(partyType==='supplier'?'suppliers':'customers')+'.create',partyedit:(S.parties.find(p=>p.id===selected)?.type==='supplier'?'suppliers':'customers')+'.edit',account:'banks.create',user:'settings.users.manage',expense:'expenses.create',receive:'customers.collect',pay:'suppliers.pay',deposit:'banks.deposit_withdraw',withdraw:'banks.deposit_withdraw',cashtransfer:'banks.transfer'}[b];if(action.startsWith('site:')&&['audit','archived','unarchive'].includes(b))return 'settings.users.manage';if(action.startsWith('site:')&&['user','new-user','save-user'].includes(b))return 'settings.users.manage';if(action.startsWith('site:')&&['backup','previous-backup','restore','desktop-import','review-import','confirm-import'].includes(b))return b==='desktop-import'?'settings.legacy.import':'settings.backup.manage';if(action==='site:account-menu')return null;if(action.startsWith('site:')&&b.includes('account'))return b.includes('archive')?'banks.delete':b.includes('adjust')?'banks.balance_correct':'banks.edit';if(action.startsWith('site:archive-product'))return 'products.delete';if(a==='save-branding')return 'settings.branding.manage';return null}

// Preserve the current viewport when updating an existing screen.
function captureViewPosition(){
 const phone=document.querySelector('#phone'),content=phone?.querySelector('#content'),sheet=phone?.querySelector('.sheet'),active=document.activeElement;
 return {view:phone?.dataset.view,selected:phone?.dataset.recordOwner,top:content?.scrollTop||0,left:content?.scrollLeft||0,
  lists:[...phone?.querySelectorAll('table[data-window-key]')||[]].map(t=>({key:t.dataset.windowKey,top:t.closest('.register-scroll')?.scrollTop||0,left:t.closest('.register-scroll')?.scrollLeft||0})),
  sheetTitle:sheet?.getAttribute('aria-label'),sheetTop:sheet?.querySelector('.sheet-body')?.scrollTop||0,
  focus:sheet?.contains(active)&&active?.name?{name:active.name,start:active.selectionStart,end:active.selectionEnd}:null};
}
function restoreViewPosition(saved){
 const phone=document.querySelector('#phone');phone.dataset.recordOwner=String(selected);
 if(saved.view===view&&saved.selected===String(selected)){
  const content=phone.querySelector('#content');if(content){content.scrollTop=saved.top;content.scrollLeft=saved.left}
  for(const old of saved.lists){const table=[...phone.querySelectorAll('table[data-window-key]')].find(t=>t.dataset.windowKey===old.key),scroller=table?.closest('.register-scroll');if(scroller){scroller.scrollTop=listWindowResetScroll===old.key?0:old.top;scroller.scrollLeft=old.left}}
 }
 listWindowResetScroll=null;
 const sheet=phone.querySelector('.sheet');if(sheet&&sheet.getAttribute('aria-label')===saved.sheetTitle){sheet.classList.add('sheet-update');const body=sheet.querySelector('.sheet-body');if(body)body.scrollTop=saved.sheetTop;
  if(saved.focus){const input=[...sheet.querySelectorAll('input,textarea,select')].find(e=>e.name===saved.focus.name);if(input){input.focus({preventScroll:true});if(input.setSelectionRange&&saved.focus.start!==null)try{input.setSelectionRange(saved.focus.start,saved.focus.end)}catch{}}}
 }
}
render=function(){const position=captureViewPosition();const phone=document.querySelector('#phone');if(!ready){phone.dataset.appearance=previewAppearance29;phone.innerHTML='<main class="auth-screen"><p>جارٍ فتح المحل…</p></main>';return}if(!actor){phone.dataset.appearance=previewAppearance29;phone.setAttribute('style',themeStyle('login'));phone.innerHTML=authScreen();translateUi(phone);return}baseRender();decorateListWindows();if(view==='operations')phone.querySelectorAll('[data-action="open:actions"]').forEach(e=>e.closest('.list-actions')?.remove());phone.querySelectorAll('[data-action="go:offset"],[data-action="new:offset"],[data-action="offset-review"]').forEach(e=>e.remove());const header=phone.querySelector('.app-head');if(header){const button=document.createElement('button');button.className='icon-btn outline site-profile';button.dataset.action='site:account-menu';button.setAttribute('aria-label','حساب المستخدم');button.innerHTML=icon('people');header.append(button)}if(view==='home'){if(!can('reports.view'))phone.querySelector('.daily-split')?.remove();for(const title of [...phone.querySelectorAll('.section-title')]){const label=title.querySelector('h2')?.textContent;if(label==='الحسابات والأرصدة'||label==='آخر الفواتير'&&!can('records.view')){let next=title.nextElementSibling;while(next&&!next.classList.contains('section-title')){const after=next.nextElementSibling;next.remove();next=after}title.remove()}}}phone.classList.toggle('busy',busy);phone.querySelector('.status b')?.replaceChildren(time());const sub=phone.querySelector('.app-head .sub');if(sub)sub.innerHTML=`<span class="dot"></span>${esc(actor.name)} · ${busy?'جارٍ الحفظ':'محفوظ على الجهاز'}`;if(view==='home'&&cart.length){const resume=document.createElement('button');resume.className='pos-resume';resume.dataset.action='pos:resume';resume.textContent=`متابعة مسودة ${saleType==='sale'?'البيع':'الشراء'} · ${cart.length} أصناف`;phone.querySelector('#content')?.prepend(resume)}if(['operations','reports'].includes(view)){const toolbar=document.createElement('div');toolbar.className='data-toolbar';toolbar.innerHTML='<button data-action="site:export">تصدير السجل</button>';phone.querySelector('#content')?.append(toolbar)}phone.querySelectorAll('.nav button').forEach(button=>{if(button.classList.contains('active'))button.setAttribute('aria-current','page');else button.removeAttribute('aria-current')});phone.querySelectorAll('[data-action]').forEach(button=>{let cap;try{cap=permissionFor(button.dataset.action)}catch{}if(cap&&!can(cap)){button.disabled=true;button.setAttribute('aria-disabled','true');button.title='غير متاح بصلاحيات حسابك'}});phone.querySelectorAll('.notice').forEach(el=>{el.textContent=el.textContent.replace('الأرقام في المعاينة من نفس سجلات البيع والمصاريف المعروضة.','الأرقام من المستندات الفعالة في الفترة المختارة.').replace('هذه معاينة لشكل الإجراءات. لا تصل إلى بيانات التطبيق أو تعدّلها.','').replace('المعاينة الحالية','الموقع').replace('في المعاينة','').replace('معاينة تصميم · بيانات تجريبية','')});phone.querySelectorAll('p').forEach(el=>{if(el.textContent==='معاينة تصميم · بيانات تجريبية')el.remove()});translateUi(phone);setBusyButtons();restoreViewPosition(position);requestAnimationFrame(()=>{fitProductNames(phone);focusLocatedRecord(phone)})};

async function authenticate(setup){const f=form('site-auth-form'),username=String(f.username||'').trim().toLowerCase();if(!username||!f.password)return fail('أدخل اسم المستخدم وكلمة المرور');if(setup){if(verifiedSetupIdentity){f.name=verifiedSetupIdentity.name;f.shop=verifiedSetupIdentity.shop}if(!f.name?.trim()||!f.shop?.trim()||f.password.length<4)return fail('أدخل الاسم واسم المحل وكلمة مرور من 4 أحرف على الأقل');if(appUsers.length)throw Error('تم إنشاء حساب المالك بالفعل');const owner={id:crypto.randomUUID(),name:f.name.trim(),username,role:'owner',capabilities:[...CAPABILITIES],active:true,password:await passwordDigest(f.password),createdAt:new Date().toISOString()};reset(true);S.branding=f.shop.trim();S.brandInfo={phone:'',address:'',footer:'شكرًا لزيارتكم'};S.records.forEach(r=>r.date=today());S.auditEvents=[];S.users=[];await database.replace(stateForSave(),[owner]);await loadUsers();await makeSession(owner)}else{const user=appUsers.find(u=>u.username===username&&u.active!==false);if(!user||!await verifyPassword(f.password,user.password))return fail('اسم المستخدم أو كلمة المرور غير صحيحة');await makeSession(user)}view='home';activeTab='home';dateFrom=dateTo=today();period='today';history=[];restorePosDraft();render()}
async function saveUser(){const f=form(),old=appUsers.find(u=>u.id===userEdit),username=String(f.username||'').trim().toLowerCase();if(!f.name?.trim()||!username||appUsers.some(u=>u.username===username&&u.id!==old?.id))return fail('أدخل اسمًا واسم مستخدم فريدًا');if(!old&&f.password.length<4||f.password&&f.password.length<4)return fail('كلمة المرور يجب أن تكون 4 أحرف على الأقل');const role=old?.role==='owner'?'owner':f.role;if(!roleNames[role])return fail('اختر صلاحية صحيحة');const user={...old,id:old?.id||crypto.randomUUID(),name:f.name.trim(),username,role,active:old?.id===actor.id?true:f.active!=='false',capabilities:role==='owner'?[...CAPABILITIES]:[...PRESETS[role]],password:f.password?await passwordDigest(f.password):old.password,updatedAt:new Date().toISOString()};await database.put('users',user);await loadUsers();if(actor.id===user.id)actor=publicUser(user);modal=null;render();toast('تم حفظ المستخدم')}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
async function exportBackup(){const payload={format:'alkarna-web-backup',schemaVersion:1,createdAt:new Date().toISOString(),state:stateForSave(),users:await database.all('users')};download('alkarna-'+today()+'.json',JSON.stringify(payload,null,2));S.lastBackupAt=new Date().toISOString();toast('تم تنزيل النسخة الاحتياطية')}
async function reviewImport(){const pasted=document.querySelector('#backup-json')?.value?.trim(),file=document.querySelector('#backup-file')?.files?.[0]||(pasted?{name:'نسخة ملصقة',size:new Blob([pasted]).size,text:async()=>pasted}:null);if(!file)return fail('اختر ملف النسخة أو الصق نصها');if(file.size>40*1024*1024)return fail('الملف أكبر من 40 ميغابايت');let parsed;try{parsed=JSON.parse(await file.text())}catch{return fail('الملف ليس JSON صالحًا')}if(parsed.format==='alkarna-web-backup'&&parsed.schemaVersion===1){validateState(parsed.state);if(!Array.isArray(parsed.users))throw Error('حسابات المستخدمين مفقودة');restorePlan=parsed}else if(parsed.format==='conta-backup'&&parsed.schemaVersion===1){restorePlan={state:desktopToState(parsed),users:await database.all('users')}}else throw Error('صيغة النسخة غير مدعومة. اختر نسخة الكرنه أو نسخة كونتا أوفلاين الرسمية.');restoreFile=file.name;showModal('site-import-review')}
function desktopToState(raw){const c=raw.collections;if(!c||!['products','parties','warehouses','documents','paymentAccounts','financialMovements'].every(k=>Array.isArray(c[k])))throw Error('أجزاء النسخة الرسمية ناقصة');const map=(rows)=>new Map(rows.map((r,i)=>[String(r.id),i+1]));const products=map(c.products),parties=map(c.parties),accounts=map(c.paymentAccounts),warehouses=new Map(c.warehouses.map(w=>[String(w.id),w.name]));const n=v=>{const value=Number(v||0);if(!Number.isFinite(value))throw Error('مبلغ غير صالح في النسخة');return value};const state={products:c.products.map(p=>({id:products.get(String(p.id)),desktopId:p.id,name:p.name,sku:p.barcode||p.sku||'',price:n(p.piecePrice),cost:n(p.pieceCost??p.lastPurchaseCost??p.legacyOpeningCost),stocks:Object.fromEntries(c.warehouses.map(w=>[w.name,n(p.stocks?.[w.id])])),qty:0,desktop:p})),parties:c.parties.map(p=>{if(n(p.receivable)>0&&n(p.payable)>0)throw Error('النسخة تحتوي طرفًا له رصيدان متقابلان؛ لم تُغيّر أي بيانات. يحتاج استيراده إلى نموذج الأرصدة الثنائية.');return{id:parties.get(String(p.id)),desktopId:p.id,name:p.name,phone:p.phone||'',type:p.partyType||p.type,balance:(n(p.receivable)-n(p.payable))*((p.partyType||p.type)==='supplier'?-1:1),desktop:p}}),accounts:c.paymentAccounts.map(a=>({id:accounts.get(String(a.id)),desktopId:a.id,name:a.name,balance:n(a.balance)})),warehouses:c.warehouses.map(w=>w.name),warehouse:c.warehouses.find(w=>w.isSalesDefault)?.name||c.warehouses[0]?.name,records:[],users:[],branding:'الكرنه',opening:{accounts:{},parties:{},stocks:{}},desktopOriginal:raw};const kinds={sale:'sale',purchase:'purchase',expense:'expense',payment:'receive',transfer:'stocktransfer','account-transfer':'transfer',adjustment:'adjustment',offset:'offset','account-adjustment':'deposit'};state.records=c.documents.map((r,i)=>{if(!kinds[r.kind])throw Error('نوع مستند غير مدعوم للاستيراد: '+r.kind+'؛ البيانات الحالية لم تتغير');if(['sale','purchase','transfer','adjustment'].includes(r.kind)&&(r.lines||[]).some(l=>!l.productId))throw Error('النسخة تحتوي بنودًا بلا منتج؛ لم تتغير بياناتك');const kind=r.kind==='payment'?(r.partyCashDirection==='pay'?'pay':'receive'):r.kind==='account-adjustment'?(r.accountAdjustmentDirection==='withdrawal'?'withdraw':'deposit'):kinds[r.kind],date=(r.businessDate||r.occurredAt||raw.createdAt).slice(0,10),lines=(r.lines||[]).filter(l=>l.productId!=null).map(l=>({product:products.get(String(l.productId)),name:l.description||c.products.find(p=>String(p.id)===String(l.productId))?.name||'',qty:n(l.quantity),price:n(l.unitPrice),costAtSale:l.costAtSale!=null?n(l.costAtSale):undefined,delta:n(l.balanceAfter)-n(l.balanceBefore)}));return {id:i+101,desktopId:r.id,number:r.number,kind,title:r.title||r.partyName||kind,subtitle:r.note||'',date,time:(r.occurredAt||'').slice(11,16)||'00:00',total:n(r.total),paid:n(r.paidTotal??r.cashAmount),due:n(r.dueTotal),profit:lines.reduce((sum,l,j)=>sum+n(r.lines[j]?.grossProfit),0),account:accounts.get(String(r.fromAccountId))||accounts.get(String(c.financialMovements.find(m=>String(m.documentId)===String(r.id))?.accountId))||accounts.get(String(c.paymentAccounts.find(a=>a.code===r.paymentMethod||a.id===r.paymentMethod)?.id))||null,to:accounts.get(String(r.toAccountId))||null,party:parties.get(String(r.partyId))||null,warehouse:warehouses.get(String(r.warehouseId))||state.warehouse,from:warehouses.get(String(r.warehouseId)),toWarehouse:warehouses.get(String(r.destinationWarehouseId)),newQty:n(r.lines?.[0]?.balanceAfter),voided:r.status==='voided',revision:n(r.revision),lines,desktop:r}});state.products.forEach(p=>p.qty=p.stocks[state.warehouse]||0);state.opening.accounts=Object.fromEntries(state.accounts.map(a=>[a.id,a.balance]));state.opening.parties=Object.fromEntries(state.parties.map(p=>[p.id,p.balance]));state.opening.stocks=Object.fromEntries(state.products.map(p=>[p.id,{...p.stocks}]));for(const r of state.records.filter(r=>!r.voided)){for(const a of state.accounts)state.opening.accounts[a.id]-=accountDelta(r,a.id);for(const p of state.parties)state.opening.parties[p.id]-=partyDelta(r,p.id);for(const l of r.lines){if(r.kind==='sale')state.opening.stocks[l.product][r.warehouse]+=l.qty;if(r.kind==='purchase')state.opening.stocks[l.product][r.warehouse]-=l.qty;if(r.kind==='adjustment')state.opening.stocks[l.product][r.warehouse]-=l.delta;if(r.kind==='stocktransfer'){state.opening.stocks[l.product][r.from]+=l.qty;state.opening.stocks[l.product][r.toWarehouse]-=l.qty}}}for(const record of state.records){if(record.paid>0&&!record.account&&!['stocktransfer','adjustment','offset'].includes(record.kind))throw Error('لا يمكن تحديد وسيلة دفع مستند من النسخة؛ لم يتم استيرادها');if(['sale','purchase'].includes(record.kind)&&record.paid>0&&record.paid!==record.total)throw Error('النسخة تحتوي دفعًا جزئيًا. هذا الموقع يعمل بالدفع الكامل أو الملاحظة.');if(record.kind==='offset')throw Error('التقاص في النسخة يحتاج ربط الطرف المقابل؛ لم تتغير بياناتك')}state.categories=(c.productCategories||[]).map((x,i)=>({id:i+1,desktopId:x.id,name:x.name}));for(const p of state.products)p.categoryId=state.categories.find(x=>String(x.desktopId)===String(p.desktop.categoryId))?.id||null;state.currency={code:c.appSettings?.find(x=>x.currency?.code)?.currency.code||'MRU',availableCodes:['MRU']};state.salesWarehouse=state.warehouse;validateState(state);return state}
function printInvoice(){const r=S.records.find(r=>r.id===selected);if(!r)return;let root=document.querySelector('#print-root');if(!root){root=document.createElement('section');root.id='print-root';root.hidden=true;document.body.append(root)}root.innerHTML=`<h1>${esc(S.branding)}</h1><p>${esc(S.brandInfo?.address||'')} · ${esc(S.brandInfo?.phone||'')}</p><div class="print-meta"><span>${esc(documentLabels[r.kind])} · ${r.number||r.kind.toUpperCase()+'-'+r.id}</span><span>${r.date} ${r.time}</span></div><h2>${esc(r.title)}</h2>${r.voided?'<p>ملغاة</p>':''}<table><thead><tr><th>الرقم</th><th>المنتج / البيان</th><th>الكمية</th><th>سعر الوحدة</th><th>المبلغ</th></tr></thead><tbody>${r.lines.length?r.lines.map((l,i)=>`<tr><td>${i+1}</td><td>${esc(l.name)}</td><td>${formatNumber(l.qty)}</td><td>${formatNumber(l.price)}</td><td>${formatNumber(l.qty*l.price)}</td></tr>`).join(''):`<tr><td>1</td><td>${esc(r.title)}</td><td>1</td><td>${r.total}</td><td>${r.total}</td></tr>`}</tbody></table><p class="total">الإجمالي: ${formatNumber(r.total)} MRU</p><p>${['stocktransfer','adjustment','offset'].includes(r.kind)?'عملية غير نقدية':r.due?'ملاحظة على الحساب — دون حركة نقدية':'دفع مباشر'}</p><p>${esc(r.note||'')}</p><p>${esc(S.brandInfo?.footer||'')}</p>`;translateUi(root);window.print()}
function exportRecords(){return S.records.filter(r=>(filter==='void'?r.voided:!r.voided)&&(view!=='operations'||filter==='all'||filter==='void'||r.kind===filter)&&inPeriod(r)&&(!search||searchMatches(r.title+' '+r.id+' '+r.kind+' '+(documentLabels[r.kind]||'')+' '+(r.number||''),search)))}
async function exportExcel(){const records=exportRecords();if(!records.length)return fail('لا توجد مستندات ضمن الفلاتر المختارة');await offerExport('alkarna-records-'+today()+'.xlsx',recordWorkbook([{name:translateText('الملخص'),rows:[['البيان','القيمة'],['المحل',S.branding],['الفترة والنوع',exportScope()],['عدد المستندات',records.length],['العملة','MRU']].map((row,i)=>row.map((value,j)=>typeof value==='string'&&(i===0||j===0)?translateText(value):value))},...recordExportData(S,records,documentLabels,{language:appLanguage()})],{language:appLanguage()}));}
