async function printRecords(){const records=exportRecords();if(!records.length)return fail('لا توجد مستندات ضمن الفلاتر المختارة');let root=document.querySelector('#print-root');if(!root){root=document.createElement('section');root.id='print-root';root.hidden=true;document.body.append(root)}root.dir=appLanguage()==='fr'?'ltr':'rtl';root.innerHTML=reportHtml(reportModel(S,records,documentLabels,translateText(exportScope()),{language:appLanguage()}));modal=null;render();await document.fonts.ready;window.print()}



async function siteAction(action){const [,command,id]=action.split(':');if(command==='party-metric'){const parts=action.split(':'),type=parts[2],party=parts[3]==='all'?null:Number(parts[3]),key=parts[4];if(!['customer','supplier'].includes(type)||!Object.hasOwn(partyMetricLabels,key)||party!==null&&!S.parties.some(p=>p.id===party&&p.type===type))return fail('الحساب غير موجود');partyMetricSelection={type,id:party,key};modal='site-party-metric';return render()}if(command==='seed-demo')return fail('لا توجد معاملات تجريبية في هذه النسخة.');if(command==='account-menu'){showModal('site-account-menu');return}if(command==='support')return showModal('site-support');if(command==='audit'){modal='site-audit';render();return}if(command==='archived'){modal='site-archived';render();return}if(command==='unarchive'){const item=(action.split(':')[2]==='product'?S.products:S.accounts).find(p=>p.id===Number(action.split(':')[3]));if(item)item.archived=false;render();return}if(command==='language'){const fields=[...document.querySelectorAll('#site-auth-form input')].map(e=>[e.name,e.value]);localStorage.setItem('alkarna-site-language',id==='fr'?'fr':'ar');modal=null;render();for(const [name,value] of fields){const input=document.querySelector('#site-auth-form [name='+name+']');if(input)input.value=value}return}if(command==='login'||command==='setup')return authenticate(command==='setup');if(command==='logout')return logout();if(command==='new-user'){userEdit=null;return showModal('site-user')}if(command==='user'){userEdit=id;return showModal('site-user')}if(command==='save-user')return saveUser();if(command==='previous-backup'){const previous=await database.get('meta','safety-backup');if(!previous?.backup)return fail('لا توجد استعادة سابقة');download('alkarna-before-restore.json',JSON.stringify({format:'alkarna-web-backup',schemaVersion:1,createdAt:previous.savedAt,...previous.backup},null,2));return}if(command==='backup')return exportBackup();if(command==='restore'||command==='desktop-import'){restorePlan=null;return showModal('site-import')}if(command==='review-import')return reviewImport();if(command==='confirm-import'){const all=await database.all('users');await database.put('meta',{id:'safety-backup',backup:{state:stateForSave(),users:all},savedAt:new Date().toISOString()});await database.replace(restorePlan.state,restorePlan.users);S=structuredClone(restorePlan.state);await loadUsers();restorePlan=null;modal=null;await logout();toast('تمت الاستعادة. سجّل الدخول بحساب النسخة.');return}if(command==='print')return printInvoice();if(command==='export')return showModal('site-export');if(command==='export-excel')return exportExcel();if(command==='export-pdf')return exportPdf();if(command==='export-print')return printRecords();if(command==='edit-account'){selected=Number(id);return showModal('site-account-edit')}if(command==='save-account'){const name=form().name?.trim();if(!name||S.accounts.some(a=>a.name===name&&a.id!==selected))return fail('أدخل اسمًا فريدًا');S.accounts.find(a=>a.id===selected).name=name;modal=null;return render()}if(command==='account-adjust'){selected=Number(id);return showModal('site-account-adjust')}if(command==='post-account-adjust'){const f=form(),a=S.accounts.find(a=>a.id===selected),desired=Number(f.balance);if(!Number.isFinite(desired)||desired<0||!f.note?.trim())return fail('أدخل رصيدًا غير سالب وسبب التصحيح');const delta=Math.round((desired-a.balance)*100)/100;if(delta===0)return fail('الرصيد لم يتغير');return commitRecord({...newRecord(delta>0?'deposit':'withdraw'),title:'تصحيح رصيد '+a.name,note:f.note,total:Math.abs(delta),paid:Math.abs(delta),account:a.id})}if(command==='archive-product'){const p=S.products.find(p=>p.id===Number(id));if(Object.values(p.stocks).some(q=>q>0))return fail('صحّح رصيد المنتج إلى صفر قبل أرشفته');p.archived=true;view='inventory';activeTab='inventory';return render()}if(command==='archive-account'){const a=S.accounts.find(a=>a.id===Number(id));if(a.balance!==0)return fail('حوّل أو صحّح الرصيد إلى صفر قبل الأرشفة');a.archived=true;return render()}}

act=async function(action){if(window.NativeHost&&!NativeHost.licenseAllowed()){NativeHost.openActivation();return}if(action==='site:activation'){savePosDraft();NativeHost.openActivation();return}if(action.startsWith('source:')&&S.records.find(r=>r.id===Number(action.split(':')[1]))?.kind==='offset')return fail('التقاص غير متاح');if(['go:offset','new:offset','offset-review','post-offset'].includes(action)||action==='commit-pending'&&pendingRecord?.kind==='offset')return fail('التقاص غير متاح');if(busy)return;if(!actor&&!['site:login','site:setup'].includes(action)&&!action.startsWith('site:language:'))return;let cap;try{cap=permissionFor(action)}catch{return fail('تحقّق من بيانات النموذج')}if(cap&&!can(cap))return fail('لا تسمح صلاحيات حسابك بهذا الإجراء');const beforeDraft=posDraftSnapshot(),before=structuredClone(S),beforeView={view,activeTab,selected,modal,editingId,cart:structuredClone(cart)},beforeJSON=JSON.stringify(stateForSave());let result;try{busy=true;setBusyButtons();if(action.startsWith('site:'))result=await siteAction(action);else if(action==='save-branding'){const f=form('branding-form');if(!f.name?.trim())return fail('أدخل اسم المحل');S.branding=f.name.trim();S.brandInfo={...S.brandInfo,...features.admin.preserveBranding(),phone:f.phone?.trim()||'',address:f.address?.trim()||'',footer:f.footer?.trim()||''};render()}else if(action==='save-user'||action.startsWith('user:')){if(!can('settings.users.manage'))return fail('غير متاح');if(action==='save-user')result=await saveUser();else{userEdit=appUsers[Number(action.split(':')[1])]?.id;showModal('site-user')}}else if(action==='backup:save')result=await exportBackup();else if(action.startsWith('backup:'))result=showModal('site-import');else if(action==='login')result=logout();else if(action==='open:user'){userEdit=null;result=showModal('site-user')}else if(action==='open:language')result=showModal('site-language');else{result=await baseAct(action);if(period==='today')dateFrom=dateTo=today()}if(actor&&beforeJSON!==JSON.stringify(stateForSave())){S.auditEvents??=[];S.auditEvents.push({id:crypto.randomUUID(),at:new Date().toISOString(),user:actor.id,userName:actor.name,action});await database.save(stateForSave());await features.afterSave();if(['post-sale','post-cash','post-party','commit-pending','confirm-void','save-product','save-party','save-account','save-branding'].includes(action))toast('تم الحفظ على الجهاز')}return result}catch(e){if(actor){S=before;view=beforeView.view;activeTab=beforeView.activeTab;selected=beforeView.selected;modal=beforeView.modal;editingId=beforeView.editingId;cart=beforeView.cart;posRestoreDraft(beforeDraft);render()}fail(e.message||'تعذّر تنفيذ العملية')}finally{busy=false;savePosDraft();setBusyButtons();if(ready&&actor){document.querySelector('#phone')?.classList.remove('busy');const sub=document.querySelector('.app-head .sub');if(sub)sub.innerHTML=`<span class="dot"></span>${esc(S.branding)} · ${esc(actor.name)} · محفوظ على الجهاز`}}};

async function boot(){render();try{await database.open();await loadUsers();if(!appUsers.length)verifiedSetupIdentity=await readSetupIdentity();const saved=await database.load();if(saved){validateState(saved);const beforeUpgrade=structuredClone(saved),changed=prepareFeatureState(saved);S=saved;const namesChanged=shortenProductNames(S);if(changed||namesChanged){if(!await database.get('snapshots','before-feature-upgrade-v2'))await database.put('snapshots',{id:'before-feature-upgrade-v2',state:beforeUpgrade,updatedAt:new Date().toISOString()});await database.save(S)}syncStock();refreshUserState()}authMode=appUsers.length?'login':'setup';await readSession();dateFrom=dateTo=today();period='today';ready=true;view='home';activeTab='home';restorePosDraft();render();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{})}catch(e){ready=true;actor=null;document.querySelector('#phone').innerHTML=`<main class="auth-screen"><section class="auth-card"><h1>تعذّر فتح المحل</h1><p>${esc(e.message)}</p><p>تحقّق من إتاحة تخزين الموقع في إعدادات المتصفح. لم تُستبدل بياناتك.</p></section></main>`}}
let localeUpdateQueued=false;
if(typeof MutationObserver!=='undefined')new MutationObserver(()=>{if(appLanguage()!=='fr'||localeUpdateQueued)return;localeUpdateQueued=true;queueMicrotask(()=>{localeUpdateQueued=false;const root=document.querySelector('#phone');if(root)translateUi(root)})}).observe(document.querySelector('#phone'),{subtree:true,childList:true,characterData:true});
const features=installFeatures({
 get siteAction(){return siteAction},set siteAction(value){siteAction=value},
 get permissionFor(){return permissionFor},set permissionFor(value){permissionFor=value},
 get engineDispatch(){return baseAct},set engineDispatch(value){baseAct=value},
 get actor(){return actor},get users(){return appUsers},
 get userEdit(){return userEdit},set userEdit(value){userEdit=value},
 capabilities:CAPABILITIES,form,can,today,time,modalMarkup,offerExport,exportRecords,exportScope,boundedTableHtml,translateUi,passwordDigest,database,desktopToState,stateForSave,download,logout,fail,
 async persistUser(user){await database.put('users',user);await loadUsers();if(actor?.id===user.id)actor=publicUser(user)}
});
await boot();

function protectedDisplayValues(){
 const values=new Set([S?.branding,actor?.name,...(S?.categories||[]).map(c=>c.name),...(S?.products||[]).map(p=>p.name),...(S?.parties||[]).map(p=>p.name),...(appUsers||[]).map(p=>p.name),...(S?.records||[]).map(r=>r.note),verifiedSetupIdentity?.name,verifiedSetupIdentity?.shop].filter(Boolean));
 for(const a of S?.accounts||[])if(!['نقدي','بنكيلي','مصرفي','السداد','أمانتي','بيم'].includes(a.name))values.add(a.name);
 for(const w of S?.warehouses||[])if(!['المخزن الرئيسي','مخزن الاحتياط'].includes(w.name||w))values.add(w.name||w);
 return values;
}
function translateUi(root){
 const language=appLanguage();root.dir=language==='fr'?'ltr':'rtl';document.documentElement.lang=language;document.documentElement.dir=root.dir;document.title=language==='fr'?'AlKarna':'الكرنه';if(language!=='fr')return;
 const protectedValues=protectedDisplayValues(),walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];
 while(walker.nextNode())nodes.push(walker.currentNode);
 for(const node of nodes){const parent=node.parentElement,value=node.textContent.trim(),systemLabel=parent?.closest('.nav,.section-title,.sheet-head,.app-head h1,thead,.party-stat-label,.party-summary-heading,.summary-head,.metric-label,.account-appearance h3,.field>label,.catalog-copy,.catalog-item>strong,.catalog-item>small');if(!value||parent?.closest('[data-user-content],.locale-switch,input,textarea,script,style')||protectedValues.has(value)&&!systemLabel)continue;const translated=translateText(node.textContent);if(translated!==node.textContent)node.textContent=translated;}
 for(const element of root.querySelectorAll('[aria-label],[placeholder],[title],[alt]'))for(const key of ['aria-label','placeholder','title','alt']){const value=element.getAttribute(key);if(value){const out=translateText(value);if(out!==value)element.setAttribute(key,out)}}
}

function activityName(action){const key=action.split(':')[0];return {'post-sale':'تسجيل فاتورة','post-cash':'تسجيل حركة مالية','post-party':'تسجيل قبض أو دفع','commit-pending':'تسجيل حركة أو تسوية','confirm-void':'إلغاء مستند','save-product':'حفظ منتج','save-party':'حفظ طرف','save-account':'إضافة حساب','save-branding':'تعديل بيانات المحل','warehouse-edit':'تعديل مخزن','warehouse-create':'إضافة مخزن','site':'إدارة المحل'}[key]||'تحديث البيانات'}

function setBusyButtons(){for(const button of document.querySelectorAll('#phone button')){if(busy&&!button.disabled){button.dataset.busyDisabled='true';button.disabled=true}else if(!busy&&button.dataset.busyDisabled){button.disabled=false;delete button.dataset.busyDisabled}}}

function savePosDraft(){if(!actor)return;try{const key='alkarna-pos-draft:'+actor.id;if(cart.length)localStorage.setItem(key,JSON.stringify(posDraftSnapshot()));else localStorage.removeItem(key)}catch{if(cart.length)toast('تعذّر حفظ المسودة. أبقِ الصفحة مفتوحة حتى إتمام الفاتورة.')}}
function restorePosDraft(){if(!actor)return;try{const raw=localStorage.getItem('alkarna-pos-draft:'+actor.id);if(raw)posRestoreDraft(JSON.parse(raw))}catch{}}

function selectPosNumericValue(event){if(event.target.matches?.('input[data-pos-select-all]'))event.target.select()}
document.addEventListener('focusin',selectPosNumericValue);
document.addEventListener('click',selectPosNumericValue);

globalThis.addEventListener?.('resize',()=>requestAnimationFrame(()=>fitProductNames(document.querySelector('#phone'))));

document.addEventListener('click',event=>{if(event.target.closest('[data-product-scan]')){const input=document.querySelector('#sheet-form input[name=sku]');if(input)scanProductBarcode(input,{onError:message=>{error(message);toast(message)}})}});

document.addEventListener('change',event=>{if(event.target.id==='backup-file'){const caption=event.target.closest('.backup-file-picker')?.querySelector('[data-backup-file-name]');if(caption)caption.textContent=event.target.files?.[0]?.name||(localStorage.getItem('alkarna-site-language')==='fr'?'JSON · Aucun fichier sélectionné':'JSON · لم يُحدد ملف')}});
